get_ecommerce_settings.code:
final response = await client.ecommerceSettings.getEcommerceSettings();
final ecommerceSettings = (response.map as Map)['ecommerce_settings'] as Map;
print(ecommerceSettings['continue_shopping']);
print(ecommerceSettings['order_flags']);

patch_ecommerce_settings.code:
final response = await client.ecommerceSettings.patchEcommerceSettings({
  'ecommerce_settings': {
    'continue_shopping': {'continue_shopping_target': 'previous'},
    'order_filters': {'default_payment_status': 'unpaid'},
  },
});
final ecommerceSettings = (response.map as Map)['ecommerce_settings'] as Map;
print(ecommerceSettings['continue_shopping']);
print(ecommerceSettings['order_filters']);

